/**
 * `btrfs` plugin wrapper — generic host-btrfs administration (subvolumes,
 * snapshots, scrub, balance, device add/remove).
 *
 * Routes through the real, working `operation.v1.PluginService/CallMethod`
 * instead of the phantom `operation.btrfs.v1.BtrfsService` (message-only
 * proto, no `service` block, nothing on the backend ever listened for it).
 *
 * Types verified against `crates/op-plugins/src/state_plugins/btrfs_plugin.rs`
 * (2026-07-05) — `list_subvolumes`, `filesystem_df`, `filesystem_usage`,
 * `scrub_status`, `balance_status` now declare real typed outputs; the other
 * methods are mutations that return `AckOutput` ({ success: boolean }).
 */

import { pluginService } from "@/grpc/client";
import { unwrap, argsFromObject } from "./_util";

const PLUGIN_ID = "btrfs";

// ── Types ─────────────────────────────────────────────────────────────────

export interface AckOutput {
  success: boolean;
}

export interface Subvolume {
  name: string;
  path: string;
  uuid?: string | null;
}

export interface ListSubvolumesInput {
  path: string;
}

export interface ListSubvolumesOutput {
  subvolumes: Subvolume[];
}

export interface CreateSubvolumeInput {
  path: string;
}

export interface DeleteSubvolumeInput {
  path: string;
}

export interface SnapshotInput {
  source: string;
  destination: string;
  readonly?: boolean;
}

export interface ScrubStartInput {
  path: string;
}

export interface ScrubStatusInput {
  path: string;
}

export interface ScrubStatusOutput {
  state: string;
  progressPercent: number;
  errorsFound: number;
}

export interface BalanceStartInput {
  path: string;
}

export interface BalanceStatusInput {
  path: string;
}

export interface BalanceStatusOutput {
  running: boolean;
  progressPercent: number;
}

export interface FilesystemDfInput {
  path: string;
}

export interface FilesystemDfOutput {
  totalBytes: number;
  usedBytes: number;
  freeBytes: number;
  allocatedBytes: number;
}

export interface FilesystemUsageInput {
  path: string;
}

export interface FilesystemUsageOutput {
  dataBytes: number;
  metadataBytes: number;
  systemBytes: number;
  unallocatedBytes: number;
}

export interface DeviceAddInput {
  device: string;
  path: string;
}

export interface DeviceRemoveInput {
  device: string;
  path: string;
}

// ── Wrapper ───────────────────────────────────────────────────────────────

export const btrfsPlugin = {
  async listSubvolumes(input: ListSubvolumesInput): Promise<ListSubvolumesOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "list_subvolumes",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.subvolume.list@v1",
    });
    return unwrap<ListSubvolumesOutput>(resp);
  },

  async createSubvolume(input: CreateSubvolumeInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "create_subvolume",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.subvolume.create@v1",
    });
    return unwrap<AckOutput>(resp);
  },

  async deleteSubvolume(input: DeleteSubvolumeInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "delete_subvolume",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.subvolume.delete@v1",
    });
    return unwrap<AckOutput>(resp);
  },

  async snapshot(input: SnapshotInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "snapshot",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.snapshot.create@v1",
    });
    return unwrap<AckOutput>(resp);
  },

  async scrubStart(input: ScrubStartInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "scrub_start",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.scrub.start@v1",
    });
    return unwrap<AckOutput>(resp);
  },

  async scrubStatus(input: ScrubStatusInput): Promise<ScrubStatusOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "scrub_status",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.scrub.status@v1",
    });
    return unwrap<ScrubStatusOutput>(resp);
  },

  async balanceStart(input: BalanceStartInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
