      objectPath: "",
      interfaceName: "",
      methodName: "balance_start",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.balance.start@v1",
    });
    return unwrap<AckOutput>(resp);
  },

  async balanceStatus(input: BalanceStatusInput): Promise<BalanceStatusOutput> {
