      actorId: "",
      capabilityId: "cap.storage.btrfs.filesystem.df@v1",
    });
    return unwrap<FilesystemDfOutput>(resp);
  },

  async filesystemUsage(input: FilesystemUsageInput): Promise<FilesystemUsageOutput> {
    const resp = await pluginService.callMethod({
      pluginId: PLUGIN_ID,
      objectPath: "",
      interfaceName: "",
      methodName: "filesystem_usage",
      arguments: argsFromObject(input),
      actorId: "",
      capabilityId: "cap.storage.btrfs.filesystem.usage@v1",
    });
    return unwrap<FilesystemUsageOutput>(resp);
  },

  async deviceAdd(input: DeviceAddInput): Promise<AckOutput> {
    const resp = await pluginService.callMethod({
