2	 * BTRFS Subvolume & Snapshot types (operation.btrfs.v1)
3	 * @see docs/architecture-flow.md §5
4	 */
5	
6	// ── Subvolume layout ────────────────────────────────────────────────────────
7	
8	export interface BtrfsSubvolume {
9	  name: string;
10	  path: string;
11	  purpose: "audit_ledger" | "dr_state" | "vector_storage";
12	  sizeBytes: number;
13	  usedBytes: number;
14	  snapshotCount: number;
15	  lastModified: string;
16	}
17	
18	export interface GetSubvolumesResponse {
19	  subvolumes: BtrfsSubvolume[];
20	  raidLevel: string;     // e.g. "RAID-1"
21	  devices: string[];     // e.g. ["/dev/sda", "/dev/sdb"]
22	  totalBytes: number;
23	  usedBytes: number;
24	}
25	
26	// ── Snapshots ───────────────────────────────────────────────────────────────
27	
28	export interface BtrfsSnapshot {
29	  id: string;
30	  subvolume: string;
31	  createdAt: string;
32	  sizeBytes: number;
33	  parentSnapshotId?: string;
34	  pinned: boolean;          // pinned until all remotes confirm receipt
35	  pinnedRemotes: string[];  // remote names still needing this snapshot
36	}
37	
38	export interface GetSnapshotsRequest {
39	  subvolume?: string;
40	  limit?: number;
41	}
42	
43	export interface GetSnapshotsResponse {
44	  snapshots: BtrfsSnapshot[];
45	  totalCount: number;
46	}
47	
48	// ── Incremental send state ──────────────────────────────────────────────────
49	
50	export interface SendState {
51	  remoteName: string;
52	  remoteHost: string;
53	  remotePath: string;
54	  lastSentSnapshotId: string;
55	  lastSentAt: string;
56	  status: "idle" | "sending" | "error";
57	  lastError?: string;
58	  bytesTransferred: number;
59	}
60	
61	export interface GetSendStateResponse {
62	  remotes: SendState[];
63	}
64	
65	// ── DR Recovery ─────────────────────────────────────────────────────────────
66	
67	export interface DrRecoveryStatus {
68	  lastCheckpoint: string;
69	  stateSubvolCurrent: boolean; // current.json exists and valid
70	  vectorSnapshotAvailable: boolean;
71	  blocksToReplay: number;
72	  recoverySteps: string[];    // ordered recovery procedure
73	}
74	
75	export interface GetDrStatusResponse {
76	  status: DrRecoveryStatus;
