import { useState, useEffect } from "react";
import { HardDrive, Database, Activity, Shield, Loader2 } from "lucide-react";
import { btrfsPlugin, type Subvolume } from "@/grpc/plugins/btrfs";

// ── Mock fallback data (offline development only) ───────────────────────────

const MOCK_SUBVOLS: Subvolume[] = [
  { name: "@root", path: "/", uuid: null },
  { name: "@home", path: "/home", uuid: null },
  { name: "@var", path: "/var", uuid: null },
];

export default function BtrfsPage() {
  const [subvolumes, setSubvolumes] = useState<Subvolume[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const subRes = await btrfsPlugin.listSubvolumes({ path: "/" });
        setSubvolumes(subRes.subvolumes);
      } catch {
        setSubvolumes(MOCK_SUBVOLS);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-[26px] font-bold tracking-tight text-foreground">BTRFS Storage</h1>
        <p className="text-sm text-muted-foreground mt-0.5">
          Subvolume layout, snapshots, and disaster recovery status.
        </p>
      </div>

      {/* Subvolumes */}
      <div>
        <h2 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
          <Database className="h-4 w-4 text-primary" />
          Subvolumes
        </h2>
        <div className="grid gap-3 md:grid-cols-3">
          {subvolumes.map((sv) => (
            <div key={sv.name} className="rounded-lg border border-border bg-card p-3 space-y-1">
              <div className="flex items-center gap-2">
                <HardDrive className="h-3.5 w-3.5 text-primary shrink-0" />
                <span className="text-sm font-mono font-medium text-foreground">{sv.name}</span>
              </div>
              <p className="text-xs text-muted-foreground font-mono">{sv.path}</p>
              {sv.uuid && <p className="text-[10px] text-muted-foreground font-mono">{sv.uuid}</p>}
            </div>
          ))}
          {subvolumes.length === 0 && (
            <p className="text-xs text-muted-foreground col-span-full">No subvolumes found.</p>
          )}
        </div>
      </div>

      {/* Snapshots — not yet available: the btrfs plugin has no list-snapshots
          method backed by real data (see spec OPEN QUESTION BT-1). */}
      <div>
        <h2 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
          <Activity className="h-4 w-4 text-primary" />
          Snapshots
        </h2>
        <p className="text-xs text-muted-foreground">Not available — no backing method yet.</p>
      </div>

      {/* Send state / DR status — same as above: no real backing method. */}
      <div>
        <h2 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
          <Shield className="h-4 w-4 text-primary" />
          Incremental Send State &amp; Disaster Recovery
        </h2>
        <p className="text-xs text-muted-foreground">Not available — no backing method yet.</p>
      </div>
    </div>
  );
}

