// Typed method inputs / outputs.
//
// Field shapes verified 2026-07-05 against Voyage AI's official OpenAPI spec
// (github.com/voyage-ai/openapi/voyage-openapi.yml, POST /embeddings) for
// wire-level request/response fields, cross-checked against the official
// Python client (github.com/voyage-ai/voyageai-python, voyageai/client.py
// `Client.embed` + voyageai/object/embeddings.py `EmbeddingsObject`), and
// the model family catalog from docs.voyageai.com/docs/embeddings.

/// `input_type` — `None` when omitted (embed as-is); `Query`/`Document`
/// prepend Voyage's retrieval-tuned prompt before vectorizing.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum InputType {
    Query,
    Document,
}

/// `output_dtype` — `Float` (default) is supported by every model; the
/// quantized variants are only supported by models whose `ModelSpec`
/// lists them in `supported_dtypes` (currently the voyage-4/voyage-3-large
/// families and voyage-code-3).
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum OutputDtype {
    Float,
    Int8,
    Uint8,
    Binary,
    Ubinary,
}

/// `encoding_format` — `Base64` returns a base64-encoded NumPy array
/// instead of a plain JSON number array.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum EncodingFormat {
    Base64,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmbedInput {
    /// Texts to embed (OpenAPI: `input`, string|array, max 128 items).
    pub texts: Vec<String>,
    #[serde(default)]
    pub input_type: Option<InputType>,
    /// If false, over-length input raises an error instead of truncating.
    #[serde(default = "default_truncation")]
    pub truncation: bool,
    /// Only honored by models whose `ModelSpec.supported_output_dims`
    /// lists more than one value (currently voyage-4/voyage-3-large family
    /// + voyage-code-3): 2048, 1024 (provider default), 512, 256.
    #[serde(default)]
    pub output_dimension: Option<u32>,
    #[serde(default)]
    pub output_dtype: Option<OutputDtype>,
    #[serde(default)]
    pub encoding_format: Option<EncodingFormat>,
}
fn default_truncation() -> bool {
    true
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct EmbedOutput {
    pub vectors: Vec<Vec<f32>>,
    pub dimensions: u32,
    pub model: String,
    /// OpenAPI response `usage.total_tokens`.
    pub total_tokens: u32,
}
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ListModelsOutput {
    pub models: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct GetConfigOutput {
    pub config: serde_json::Value,
}

/// Model specialization family (docs.voyageai.com/docs/embeddings catalog).
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ModelFamily {
    GeneralPurpose,
    Code,
    Law,
    Finance,
    Multilingual,
}

/// Lifecycle status per the same catalog.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ModelGeneration {
    Current,
    Previous,
    Legacy,
    Deprecated,
}

/// Per-model structured spec, sourced from Voyage AI's published model
/// table (docs.voyageai.com/docs/embeddings, verified 2026-07-05).
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ModelSpec {
    pub model_id: String,
    pub family: ModelFamily,
    pub generation: ModelGeneration,
    pub context_length_tokens: u32,
    pub supported_output_dims: Vec<u32>,
    pub supported_dtypes: Vec<OutputDtype>,
    pub supported_input_types: Vec<InputType>,
}

/// The full catalog as published — not just the voyage-4 shared-space trio
/// this plugin defaults to (`VoyageModel::SHARED_SPACE`). Kept as a
/// separate read-only reference so `get_stats`/`list_models` can answer
/// "what's available" without conflating it with "what's operationally
/// selected."
fn voyage_model_catalog() -> Vec<ModelSpec> {
    use ModelFamily::*;
    use ModelGeneration::*;
    let full_dims = vec![256, 512, 1024, 2048];
    let full_dtypes = vec![
        OutputDtype::Float,
        OutputDtype::Int8,
        OutputDtype::Uint8,
        OutputDtype::Binary,
        OutputDtype::Ubinary,
    ];
    let both_input_types = vec![InputType::Query, InputType::Document];
    let float_only = vec![OutputDtype::Float];
    vec![
        // General-purpose — voyage-4 (current)
        ModelSpec { model_id: "voyage-4-large".into(), family: GeneralPurpose, generation: Current, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: full_dtypes.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-4".into(), family: GeneralPurpose, generation: Current, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: full_dtypes.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-4-lite".into(), family: GeneralPurpose, generation: Current, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: full_dtypes.clone(), supported_input_types: both_input_types.clone() },
        // General-purpose — voyage-3 (previous)
        ModelSpec { model_id: "voyage-3-large".into(), family: GeneralPurpose, generation: Previous, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: full_dtypes.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-3.5".into(), family: GeneralPurpose, generation: Previous, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-3.5-lite".into(), family: GeneralPurpose, generation: Previous, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-3".into(), family: GeneralPurpose, generation: Previous, context_length_tokens: 32_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-3-lite".into(), family: GeneralPurpose, generation: Previous, context_length_tokens: 32_000, supported_output_dims: vec![512], supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
        // General-purpose — legacy/deprecated
        ModelSpec { model_id: "voyage-large-2".into(), family: GeneralPurpose, generation: Legacy, context_length_tokens: 16_000, supported_output_dims: vec![1536], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-large-2-instruct".into(), family: GeneralPurpose, generation: Legacy, context_length_tokens: 16_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-2".into(), family: GeneralPurpose, generation: Legacy, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-lite-02-instruct".into(), family: GeneralPurpose, generation: Deprecated, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-02".into(), family: GeneralPurpose, generation: Deprecated, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-01".into(), family: GeneralPurpose, generation: Deprecated, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-lite-01".into(), family: GeneralPurpose, generation: Deprecated, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        ModelSpec { model_id: "voyage-lite-01-instruct".into(), family: GeneralPurpose, generation: Deprecated, context_length_tokens: 4_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        // Code-specialized
        ModelSpec { model_id: "voyage-code-3".into(), family: Code, generation: Current, context_length_tokens: 32_000, supported_output_dims: full_dims.clone(), supported_dtypes: full_dtypes.clone(), supported_input_types: both_input_types.clone() },
        ModelSpec { model_id: "voyage-code-2".into(), family: Code, generation: Legacy, context_length_tokens: 16_000, supported_output_dims: vec![1536], supported_dtypes: float_only.clone(), supported_input_types: vec![] },
        // Legal-specialized
        ModelSpec { model_id: "voyage-law-2".into(), family: Law, generation: Current, context_length_tokens: 16_000, supported_output_dims: vec![1024], supported_dtypes: float_only.clone(), supported_input_types: both_input_types.clone() },
